   400→// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
   401→func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
   402→	blob, err := repo.BlobObject(hash)
   403→	if err != nil {
   404→		return nil, fmt.Errorf("failed to get blob: %w", err)
   405→	}
   406→
   407→	reader, err := blob.Reader()
   408→	if err != nil {
   409→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
   410→	}
   411→	defer reader.Close()
   412→
   413→	var result T
   414→	if err := json.NewDecoder(reader).Decode(&result); err != nil {
   415→		return nil, fmt.Errorf("failed to decode: %w", err)
   416→	}
   417→
   418→	return &result, nil
   419→}
