   450→// writeTranscript writes the transcript file from in-memory content or file path.
   451→// If the transcript exceeds MaxChunkSize, it's split into multiple chunk files.
   452→func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   453→	transcript := opts.Transcript
   454→	if len(transcript) == 0 && opts.TranscriptPath != "" {
   455→		var readErr error
   456→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
   457→		if readErr != nil {
   458→			// Non-fatal: transcript may not exist yet
   459→			transcript = nil
   460→		}
   461→	}
   462→	if len(transcript) == 0 {
   463→		return nil
   464→	}
   465→
   466→	// Chunk the transcript if it's too large
   467→	chunks, err := agent.ChunkTranscript(transcript, opts.Agent)
   468→	if err != nil {
   469→		return fmt.Errorf("failed to chunk transcript: %w", err)
   470→	}
   471→
   472→	// Write chunk files
   473→	for i, chunk := range chunks {
   474→		chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
   475→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
   476→		if err != nil {
   477→			return err
   478→		}
   479→		entries[chunkPath] = object.TreeEntry{
   480→			Name: chunkPath,
   481→			Mode: filemode.Regular,
   482→			Hash: blobHash,
   483→		}
   484→	}
   485→
   486→	// Content hash for deduplication (hash of full transcript)
   487→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
   488→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
   489→	if err != nil {
