   248→			info := &CheckpointInfo{
   249→				CheckpointID:     summary.CheckpointID,
   250→				CreatedAt:        summary.CreatedAt,
   251→				CheckpointsCount: summary.CheckpointsCount,
   252→				FilesTouched:     summary.FilesTouched,
   253→				SessionCount:     summary.SessionCount,
