   265→			// Read session-level metadata to get IsTask and ToolUseID
   266→			// Task checkpoints only have one session, so read from the first session's metadata
   267→			if len(summary.SessionIDs) > 0 {
   268→				sessionID := summary.SessionIDs[0]
   269→				if sessionPaths, ok := summary.Sessions[sessionID]; ok && sessionPaths.Metadata != "" {
   270→					sessionMetadataPath := checkpointPath + "/" + sessionPaths.Metadata
   271→					if sessionFile, err := tree.File(sessionMetadataPath); err == nil {
   272→						if sessionContent, err := sessionFile.Contents(); err == nil {
   273→							var sessionMetadata checkpoint.CommittedMetadata
   274→							if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
   275→								info.IsTask = sessionMetadata.IsTask
   276→								info.ToolUseID = sessionMetadata.ToolUseID
   277→							}
   278→						}
   279→					}
